exercises.starter_code:
public class Main {
    static void swap(int[] a, int[] b) {}
    public static void main(String[] args) { int x = 5, y = 10; }
}

exercises.solution:
public class Main {
    static void swap(int[] a, int[] b) { int t = a[0]; a[0] = b[0]; b[0] = t; }
    public static void main(String[] args) {
        int[] x = {5}, y = {10};
        swap(x, y);
        System.out.println(x[0] + " " + y[0]);
    }
}
